def get_logo_bytes(variant="mini_ivory"):
    """Returns PNG bytes for PDF embedding without requiring external files."""
    if os.path.exists("logo.png"):
        with open("logo.png", "rb") as f:
            return f.read()
    mapping = {
        "main": B64_MAIN_LOGO,
        "mini": B64_MINI_LOGO,
        "mini_ivory": B64_MINI_IVORY,
        "wordmark": B64_WORDMARK
    }
    b64_str = mapping.get(variant, B64_MINI_IVORY)
    if not b64_str:
        raise ValueError("Logo base64 string not configured.")
    return base64.b64decode(b64_str)

