# --- ETHIOPIAN CALENDAR & DATA HELPERS ---
def to_ethiopian(date_val):
    if pd.isna(date_val): return ""
    try:
        dt = date_val.date() if hasattr(date_val, 'date') else date_val
        eth = Kenat(dt).get_ethiopian()
        return f"{eth['day']:02d}/{eth['month']:02d}/{eth['year']} EC ({ETH_MONTHS[eth['month']-1]})"
    except Exception:
        return str(date_val)

def to_ethiopian_short(date_val):
    if pd.isna(date_val): return ""
    try:
        dt = date_val.date() if hasattr(date_val, 'date') else date_val
        eth = Kenat(dt).get_ethiopian()
        return f"{eth['day']:02d}/{eth['month']:02d}/{eth['year']}"
    except Exception:
        return str(date_val)

def get_eth_month_label(y, m):
    try:
        y_int, m_int = int(y), int(m)
        if y_int > 0 and 1 <= m_int <= 13:
            return f"{ETH_MONTHS[m_int-1]} {y_int} EC"
    except Exception:
        pass
    return "Unknown Date"

def get_greg_from_eth(eth_y, eth_m, eth_d):
    try:
        g = Kenat(f"{eth_y}/{eth_m}/{eth_d}").get_gregorian()
        return pd.to_datetime(datetime.date(g['year'], g['month'], g['day']))
    except Exception:
        return pd.NaT

def parse_smart_eth_or_greg_date(val):
    if pd.isna(val) or str(val).strip() in ('', 'DATE', 'date', 'Date'):
        return pd.NaT
    if isinstance(val, (datetime.datetime, datetime.date, pd.Timestamp)):
        return pd.to_datetime(val)
    s = str(val).strip()
    parts = s.split('/')
    if len(parts) == 3:
        try:
            d, m, y = int(parts[0]), int(parts[1]), int(parts[2])
            if 1990 <= y <= 2021:
                g = Kenat(f"{y}/{m}/{d}").get_gregorian()
                return pd.to_datetime(datetime.date(g['year'], g['month'], g['day']))
            return pd.to_datetime(datetime.date(y, m, d))
        except Exception:
            pass
    return pd.to_datetime(s, dayfirst=True, errors='coerce')

def clean_num(val):
    if pd.isna(val): return 0.0
    try:
        s = str(val).replace(',', '').replace('ETB', '').replace('$', '').strip()
        if s in ('', '-', 'None', 'nan', '#REF!', '#N/A', '#VALUE!'): return 0.0
        return float(s)
    except Exception:
        return 0.0

def normalize_account(val):
    s = str(val).strip()
    up = s.upper()
    if up in ("COMPANY ACCOUNT", "COMPANY"):
        return "Company Account"
    if up == "SAMI":
        return "SAMI"
    if up == "JO":
        return "JO"
    return s if s and up != "NAN" else "Company Account"

def get_sheet_url():
    return st.secrets.get("eleganza_url", st.secrets.get("sofabet_url", ""))

def get_google_creds():
    scope = ['https://spreadsheets.google.com/feeds', 'https://www.googleapis.com/auth/drive']
    try:
        if "gcp_service_account" in st.secrets:
            secret_data = st.secrets["gcp_service_account"]
            if "key_base64" in secret_data:
                json_str = base64.b64decode(secret_data["key_base64"]).decode('utf-8')
                key_dict = json.loads(json_str)
                return service_account.Credentials.from_service_account_info(key_dict, scopes=scope)
            else:
                return service_account.Credentials.from_service_account_info(secret_data, scopes=scope)
    except Exception:
        return service_account.Credentials.from_service_account_file('key.json', scopes=scope)

def _get_sheets_global():
    creds = get_google_creds()
    return gspread.authorize(creds).open_by_url(get_sheet_url())

def _ensure_sheet(ws_name, headers):
    sh = _get_sheets_global()
    try:
        ws = sh.worksheet(ws_name)
        first_row = ws.row_values(1)
        if not first_row or first_row[0] != headers[0]:
            ws.insert_row(headers, index=1)
        return ws
    except gspread.WorksheetNotFound:
        ws = sh.add_worksheet(title=ws_name, rows=2000, cols=len(headers))
        ws.append_row(headers)
        return ws

def _get_all_records_robust(ws):
    try:
        all_vals = ws.get_all_values()
        if not all_vals or len(all_vals) < 2: return []
        headers = all_vals[0]
        if not headers or headers[0] == "": return []
        data = []
        for row in all_vals[1:]:
            if not any(row): continue
            if len(row) < len(headers): row += [''] * (len(headers) - len(row))
            elif len(row) > len(headers): row = row[:len(headers)]
            data.append(dict(zip(headers, row)))
        return data
    except Exception:
        return []

def _find_all_matching_rows(ws, match_fn):
    out = []
    try:
        all_vals = ws.get_all_values()
        if not all_vals or len(all_vals) < 2: return out
        headers = all_vals[0]
        for i, row in enumerate(all_vals[1:], start=2):
            padded = list(row) + [''] * (len(headers) - len(row))
            rec = dict(zip(headers, padded))
            try:
                if match_fn(rec): out.append(i)
            except Exception:
                continue
    except Exception:
        pass
    return out

def get_eleganza_tab(sheet, tab_name, anchor_col):
    try:
        raw = sheet.worksheet(tab_name).get_all_values()
        if not raw: return pd.DataFrame()
        header_idx = None
        for idx, row in enumerate(raw[:15]):
            cleaned = [str(c).strip() for c in row]
            if anchor_col in cleaned:
                header_idx = idx
                break
        if header_idx is None: return pd.DataFrame()

        headers = [str(c).strip() if str(c).strip() != '' else f"Col_{i}" for i, c in enumerate(raw[header_idx])]
        seen = {}
        unique_headers = []
        for h in headers:
            if h in seen:
                seen[h] += 1
                unique_headers.append(f"{h}_{seen[h]}")
            else:
                seen[h] = 0
                unique_headers.append(h)

        rows = raw[header_idx + 1:]
        df = pd.DataFrame(rows, columns=unique_headers)
        df = df.replace('', pd.NA).dropna(how='all')
        df = df[df[anchor_col].astype(str).str.strip() != anchor_col]
        return df.reset_index(drop=True)
    except Exception:
        return pd.DataFrame()

def build_dynamic_inventory(df_in_all, df_out_all, df_mgmt_all=None):
    """Builds live catalog & stock valuation directly from STOCK IN and Stock OUT."""
    in_df = df_in_all.copy() if df_in_all is not None and not df_in_all.empty else pd.DataFrame()
    out_df = df_out_all.copy() if df_out_all is not None and not df_out_all.empty else pd.DataFrame()

    if not in_df.empty:
        name_col = 'Item_Name' if 'Item_Name' in in_df.columns else ('ITEM NAME' if 'ITEM NAME' in in_df.columns else None)
        if name_col:
            in_df['item_key'] = in_df[name_col].astype(str).str.strip().str.lower()
            in_df = in_df[in_df['item_key'].notna() & (in_df['item_key'] != '') & (in_df['item_key'] != 'nan')]
            in_agg = in_df.groupby('item_key', as_index=False).agg(
                ITEM_NAME=(name_col, lambda x: str(x.dropna().iloc[-1]).strip()),
                ITEM_CODE=('ITEM NUMBER', lambda x: str(x.dropna().iloc[-1]).strip() if 'ITEM NUMBER' in in_df.columns and len(x.dropna()) else ""),
                CATEGORY=('CATEGORY', lambda x: str(x.dropna().iloc[-1]).strip() if 'CATEGORY' in in_df.columns and len(x.dropna()) else "Custom Furniture"),
                Measure=('Measure', lambda x: str(x.dropna().iloc[-1]).strip() if 'Measure' in in_df.columns and len(x.dropna()) else "Pcs"),
                STOCK_IN=('STOCK IN', 'sum'),
                PURCHASE_COST=('TOTAL PRICE', 'sum'),
                LAST_PRICE=('PRICE', lambda x: clean_num(x.dropna().iloc[-1]) if 'PRICE' in in_df.columns and len(x.dropna()) else 0.0),
            )
            in_agg['AVG_UNIT_COST'] = np.where(
                in_agg['STOCK_IN'] > 0,
                in_agg['PURCHASE_COST'] / in_agg['STOCK_IN'],
                in_agg['LAST_PRICE']
            )
        else:
            in_agg = pd.DataFrame(columns=['item_key', 'ITEM_NAME', 'ITEM_CODE', 'CATEGORY', 'Measure', 'STOCK_IN', 'PURCHASE_COST', 'LAST_PRICE', 'AVG_UNIT_COST'])
    else:
        in_agg = pd.DataFrame(columns=['item_key', 'ITEM_NAME', 'ITEM_CODE', 'CATEGORY', 'Measure', 'STOCK_IN', 'PURCHASE_COST', 'LAST_PRICE', 'AVG_UNIT_COST'])

    if not out_df.empty:
        out_code_col = 'ITEM NUMBER' if 'ITEM NUMBER' in out_df.columns else ('ITEM NAME' if 'ITEM NAME' in out_df.columns else None)
        if out_code_col:
            out_df['item_key'] = out_df[out_code_col].astype(str).str.strip().str.lower()
            out_agg = out_df.groupby('item_key', as_index=False).agg(
                STOCK_OUT=('STOCK OUT', 'sum'),
                SALES_REVENUE=('TOTAL PRICE', 'sum'),
                LAST_SELL_PRICE=('PRICE', lambda x: clean_num(x.dropna().iloc[-1]) if 'PRICE' in out_df.columns and len(x.dropna()) else 0.0),
            )
        else:
            out_agg = pd.DataFrame(columns=['item_key', 'STOCK_OUT', 'SALES_REVENUE', 'LAST_SELL_PRICE'])
    else:
        out_agg = pd.DataFrame(columns=['item_key', 'STOCK_OUT', 'SALES_REVENUE', 'LAST_SELL_PRICE'])

    inv = pd.merge(in_agg, out_agg, on='item_key', how='outer').fillna({
        'ITEM_NAME': '',
        'ITEM_CODE': '',
        'CATEGORY': 'Custom Furniture',
        'Measure': 'Pcs',
        'STOCK_IN': 0.0,
        'PURCHASE_COST': 0.0,
        'LAST_PRICE': 0.0,
        'AVG_UNIT_COST': 0.0,
        'STOCK_OUT': 0.0,
        'SALES_REVENUE': 0.0,
        'LAST_SELL_PRICE': 0.0,
    })

    if df_mgmt_all is not None and not df_mgmt_all.empty and 'ITEM CODE' in df_mgmt_all.columns:
        m_df = df_mgmt_all.copy()
        m_df['item_key'] = m_df['ITEM CODE'].astype(str).str.strip().str.lower()
        m_sub = m_df.drop_duplicates(subset=['item_key'])
        min_map = dict(zip(m_sub['item_key'], m_sub['MIN STOCK'].apply(clean_num))) if 'MIN STOCK' in m_sub.columns else {}
        cat_map = dict(zip(m_sub['item_key'], m_sub['CATEGORY'].astype(str))) if 'CATEGORY' in m_sub.columns else {}
        price_map = dict(zip(m_sub['item_key'], m_sub['price'].apply(clean_num))) if 'price' in m_sub.columns else {}
        inv['MIN_STOCK'] = inv['item_key'].map(min_map).fillna(5.0)
        inv['CATEGORY'] = np.where(inv['item_key'].isin(cat_map), inv['item_key'].map(cat_map), inv['CATEGORY'])
        mgmt_price = inv['item_key'].map(price_map).fillna(0.0)
    else:
        inv['MIN_STOCK'] = 5.0
        mgmt_price = 0.0

    inv['ITEM_NAME'] = np.where(inv['ITEM_NAME'].astype(str).str.strip() == "", inv['item_key'], inv['ITEM_NAME'])
    inv['ITEM_CODE'] = np.where(inv['ITEM_CODE'].astype(str).str.strip() == "", inv['ITEM_NAME'], inv['ITEM_CODE'])
    inv['STOCK_AVAILABLE'] = inv['STOCK_IN'] - inv['STOCK_OUT']
    inv['AVAIL_FOR_VAL'] = inv['STOCK_AVAILABLE'].clip(lower=0.0)
    inv['UNIT_COST'] = np.where(inv['AVG_UNIT_COST'] > 0, inv['AVG_UNIT_COST'], mgmt_price)
    inv['RETAIL_PRICE'] = np.where(
        inv['LAST_SELL_PRICE'] > 0,
        inv['LAST_SELL_PRICE'],
        np.where(mgmt_price > 0, mgmt_price, inv['UNIT_COST'] * 1.35)
    )
    inv['STOCK_VALUE'] = inv['AVAIL_FOR_VAL'] * inv['UNIT_COST']
    inv['STATUS'] = np.where(
        inv['STOCK_AVAILABLE'] <= 0, "Out of Stock",
        np.where(inv['STOCK_AVAILABLE'] <= inv['MIN_STOCK'], "Minimum Amount", "Available")
    )

    total_stock_val = float(inv['STOCK_VALUE'].sum())
    return inv.sort_values('ITEM_NAME').reset_index(drop=True), total_stock_val

