class EleganzaReportPDF(FPDF):
    def __init__(self, font_name='Helvetica'):
        super().__init__()
        self.font_name = font_name
        self.set_auto_page_break(auto=True, margin=20)
        self.set_margins(10, 10, 10)

    def footer(self):
        self.set_y(self.h - 14)
        self.set_draw_color(212, 175, 55)
        self.set_line_width(0.35)
        self.line(10, self.get_y(), self.w - 10, self.get_y())
        self.set_y(self.h - 11)
        self.set_font(self.font_name, '', 7)
        self.set_text_color(80, 80, 80)
        self.cell(0, 5, f"eleganza HOMES  |  Evolved Elegance  |  eleganza.com  |  +251 9123 4567  |  Page {self.page_no()}", align='C')

def _init_pdf():
    if font_ready:
        try:
            pdf = EleganzaReportPDF('DejaVu')
            pdf.add_font('DejaVu', '', 'DejaVuSans.ttf')
            pdf.add_font('DejaVu', 'B', 'DejaVuSans-Bold.ttf')
            return pdf
        except Exception:
            pass
    return EleganzaReportPDF('Helvetica')

def _draw_pdf_header(pdf, title, subtitle):
    f_name = pdf.font_name
    BLACK = (10, 10, 10)
    GOLD = (212, 175, 55)
    WHITE = (255, 255, 255)
    IVORY = (245, 245, 245)

    pdf.set_fill_color(*BLACK)
    pdf.rect(0, 0, pdf.w, 22, 'F')
    pdf.set_fill_color(*GOLD)
    pdf.rect(0, 22, pdf.w, 1.5, 'F')

    text_x = 10
    try:
        logo_bytes = get_logo_bytes("mini_ivory")
        pdf.image(io.BytesIO(logo_bytes), x=10, y=3.5, w=19, h=14)
        text_x = 32
    except Exception:
        text_x = 10

    pdf.set_xy(text_x, 4.5)
    pdf.set_font(f_name, 'B', 14)
    pdf.set_text_color(*WHITE)
    pdf.cell(0, 6.5, "eleganza HOMES", ln=True, align='L')

    pdf.set_xy(text_x, 11.5)
